def session_record_stamps(jsonl_text):
    """Epoch-second timestamps of EVERY parseable session record.

    The gh-1646 early-exit guard's duration input: (max − min) over the
    trial's synced session records is the agent's own wall-clock — the
    tb results.json rows carry no duration field. Corrupt lines and
