    tempDir = Directory(await tempDir.resolveSymbolicLinks());
    env = LocalExecutionEnv(cwd: tempDir.path);
    mock = _ScriptedMock();
    await mock.start();
  });

  tearDown(() async {
    await mock.close();
    if (tempDir.existsSync()) tempDir.deleteSync(recursive: true);
  });

