    'IT-1: the fix loop runs, the ledger records it, the state is correct',
    () async {
      final lines = await runScripted(ApprovalMode.unattended, [
        // Turn 1: create the script — deliberately WITHOUT the exec bit.
        const _Turn.toolCalls([
